//! Stage 8 (Android `NeuroStemmer`): a word's key is its Snowball stem, so "guitars" and "guitar"
//! are one interest. The stemmer comes from the word's script and the viewer's key language, never
//! from guessing each title's language, so one word has one key for one person on every device.
//!
//! Android vendors the Snowball 3.1.1 Java stemmers; `snowstem` is generated by the same Snowball
//! release. `rust-stemmers` predates it and stems differently (English "added", German "budget",
//! Russian "ё"), so it must not be used for keys.

use icu_properties::props::Script;
use snowstem::{Algorithm, Stemmer};

use super::chars::{is_letter, script, utf16_len};
use super::tables::{DERIVED, tables};

const STEMMERS: [(&str, Algorithm); 7] = [
    ("en", Algorithm::English),
    ("es", Algorithm::Spanish),
    ("pt", Algorithm::Portuguese),
    ("fr", Algorithm::French),
    ("de", Algorithm::German),
    ("it", Algorithm::Italian),
    ("ru", Algorithm::Russian),
];

/// Whether `word` is on the list of words key spec 2 never stems: the engine's own word lists.
#[must_use]
pub fn is_unstemmed(word: &str) -> bool {
    DERIVED.unstemmed.contains(word)
}

/// `word`, already folded and lemmatized, as a key under `key_language`.
#[must_use]
pub fn key(word: &str, key_language: &str) -> String {
    // Android has no first character to read a script from in an empty word; it stays as written.
    if word.is_empty() || is_unstemmed(word) || !word.chars().all(is_letter) {
        return word.to_string();
    }
    let Some(stemmer) = language_of(word, key_language).map(stemmer) else {
        return word.to_string();
    };
    let stem = stemmer.stem(word);
    // A stem that stems again ("casero", "caser", "cas") would drift on every pass, so the word stays.
    if utf16_len(&stem) < tables().min_stem || stemmer.stem(&stem) != stem {
        word.to_string()
    } else {
        stem.into_owned()
    }
}

/// The stemmer language for `word` under `key_language`, or `None` when the word stays as written.
#[must_use]
pub fn language_of(word: &str, key_language: &str) -> Option<&'static str> {
    let tables = tables();
    let language = match script(word.chars().next()?) {
        Some(Script::Latin) if tables.latin_stemmers.contains(key_language) => key_language,
        Some(Script::Latin) if tables.other_latin_languages.contains(key_language) => return None,
        Some(Script::Latin) => "en",
        Some(Script::Cyrillic) if !tables.other_cyrillic_languages.contains(key_language) => "ru",
        _ => return None,
    };
    STEMMERS
        .iter()
        .find(|(name, _)| *name == language)
        .map(|(name, _)| *name)
}

fn stemmer(language: &str) -> Stemmer {
    let (_, algorithm) = STEMMERS
        .iter()
        .find(|(name, _)| *name == language)
        .expect("language_of names a stemmer");
    Stemmer::create(*algorithm)
}
